use crate::{config::RiskConfig,events::SecuritySnapshot,flow::FlowBook,market::MarketMetrics,portfolio::PaperPortfolio,strategy};use std::collections::HashMap;
pub struct EngineState{pub flows:FlowBook,pub paper:PaperPortfolio,pub risks:RiskConfig,pub markets:HashMap<String,MarketMetrics>}
impl EngineState{pub fn new(r:RiskConfig)->Self{Self{flows:FlowBook::default(),paper:PaperPortfolio::default(),risks:r,markets:HashMap::new()}}pub fn evaluate(&mut self,mint:&str,s:&SecuritySnapshot)->strategy::OpportunityScore{let f=self.flows.snapshot(mint);let m=self.markets.get(mint).cloned().unwrap_or_default();strategy::score(s,&f,&m)}}